// Arma el texto de WhatsApp y el HTML del email para UNA factura.
// Tono APSOL: profesional cálido, directo, argentino, sin sonar a IA.

const f = $json;

// --- Normalización de teléfono a formato Evolution API (AR): 549XXXXXXXXXX ---
function telAR(raw) {
  let d = String(raw || '').replace(/\D/g, '');
  if (!d) return null;
  d = d.replace(/^00/, '');
  if (d.startsWith('54')) {
    if (!d.startsWith('549')) d = '549' + d.slice(2);
  } else if (d.startsWith('0')) {
    d = '549' + d.slice(1);
  } else {
    d = '549' + d;
  }
  return d;
}

// --- Formato de plata AR ---
const montoFmt = new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' })
  .format(Number(f.monto || 0));

// --- Fecha dd/mm/aaaa ---
const [y, m, d] = String(f.fecha_emision).slice(0, 10).split('-');
const fechaFmt = `${d}/${m}/${y}`;

const nombre = (f.contacto_nombre || '').trim() || 'buen día';
const nroFactura = f.numero_factura ? `N° ${f.numero_factura}` : 'de servicios';
const mora = Number(f.dias_mora || 0);
const moraTxt = mora > 0 ? ` (hace ${mora} día${mora === 1 ? '' : 's'})` : '';
const esReiteracion = Number(f.recordatorios_enviados || 0) >= 1;

const apertura = esReiteracion
  ? `Hola ${nombre}, te reitero el aviso por la factura ${nroFactura} de ${f.empresa_nombre}.`
  : `Hola ${nombre}, ¿cómo va? Te escribo de APSOL por la factura ${nroFactura} de ${f.empresa_nombre}.`;

const datosPago = [
  `Banco: ${f.cuenta_banco || '-'}`,
  `CBU: ${f.cuenta_cbu || '-'}`,
  `Alias: ${f.cuenta_alias || '-'}`,
  `Titular: ${f.cuenta_titular || '-'}`
].join('\n');

const whatsappTexto =
`${apertura}

Fue emitida el ${fechaFmt} por ${montoFmt} y todavía figura como pendiente de pago${moraTxt}.

Si ya la abonaron, avisame así la doy de baja. Si no, te dejo los datos para transferir:

${datosPago}

Cualquier cosa quedo a disposición. ¡Gracias!`;

const emailAsunto = `Recordatorio de pago — Factura ${f.numero_factura || '(servicios)'} — APSOL`;

const emailHtml =
`<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;line-height:1.5">
  <p>${apertura.replace(/\n/g, '<br>')}</p>
  <p>Fue emitida el <b>${fechaFmt}</b> por <b>${montoFmt}</b> y todavía figura como <b>pendiente de pago</b>${moraTxt}.</p>
  <p>Si ya la abonaron, avisanos así la damos de baja. Si no, dejamos los datos para transferir:</p>
  <table style="border-collapse:collapse">
    <tr><td style="padding:2px 12px 2px 0">Banco</td><td><b>${f.cuenta_banco || '-'}</b></td></tr>
    <tr><td style="padding:2px 12px 2px 0">CBU</td><td><b>${f.cuenta_cbu || '-'}</b></td></tr>
    <tr><td style="padding:2px 12px 2px 0">Alias</td><td><b>${f.cuenta_alias || '-'}</b></td></tr>
    <tr><td style="padding:2px 12px 2px 0">Titular</td><td><b>${f.cuenta_titular || '-'}</b></td></tr>
  </table>
  <p>Cualquier cosa quedamos a disposición.<br>Saludos,<br>APSOL</p>
</div>`;

return [{
  json: {
    ...f,
    telefono_wa: telAR(f.contacto_telefono),
    tiene_email: !!(f.contacto_email && String(f.contacto_email).includes('@')),
    monto_fmt: montoFmt,
    fecha_emision_fmt: fechaFmt,
    whatsapp_texto: whatsappTexto,
    email_asunto: emailAsunto,
    email_html: emailHtml
  }
}];
